-- ============================================================================
-- LOGÍSTICA PERONA — import de transportistas y rutas (Transportistas Argentina)
-- Pegar y ejecutar completo en: Supabase → SQL Editor → New query → Run
-- Es seguro re-ejecutarlo: usa ON CONFLICT (code) DO NOTHING, no duplica filas.
-- ============================================================================

-- 1) Columnas nuevas en transports (no rompen los datos existentes)
alter table transports add column if not exists code text unique;
alter table transports add column if not exists business_name text;
alter table transports add column if not exists cuit text;
alter table transports add column if not exists mobile text;
alter table transports add column if not exists whatsapp text;
alter table transports add column if not exists website text;
alter table transports add column if not exists province text;
alter table transports add column if not exists city text;
alter table transports add column if not exists address text;
alter table transports add column if not exists postal_code text;
alter table transports add column if not exists zone text;
alter table transports add column if not exists source text;
alter table transports add column if not exists verified_at date;

-- 2) Tabla nueva: rutas que recorre cada transportista
create table if not exists routes (
  id uuid primary key default gen_random_uuid(),
  code text unique,
  transport_id uuid references transports(id) on delete cascade,
  origin_province text,
  origin_city text,
  origin_lat double precision,
  origin_lng double precision,
  destination_province text,
  destination_city text,
  destination_lat double precision,
  destination_lng double precision,
  label text,
  frequency text,
  notes text,
  source text,
  verified_at date,
  created_at timestamptz not null default now()
);

-- 3) Seguridad + tiempo real, igual que el resto de las tablas
do $$
begin
  execute 'alter table routes enable row level security;';
  execute 'drop policy if exists "authenticated_all" on routes;';
  execute 'create policy "authenticated_all" on routes for all to authenticated using (true) with check (true);';
end $$;
alter publication supabase_realtime add table routes;

